19	package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;
20	
21	import org.wso2.carbon.identity.application.authentication.framework.context.AuthenticationContext;
22	import org.wso2.carbon.identity.application.authentication.framework.util.FrameworkConstants;
23	
24	/**
25	 * Javascript wrapper for Java level AuthenticationContext.
26	 * This provides controlled access to AuthenticationContext object via provided javascript native syntax.
27	 * e.g
28	 * var requestedAcr = context.requestedAcr
29	 * <p>
30	 * instead of
31	 * var requestedAcr = context.getRequestedAcr()
32	 * <p>
33	 * Also it prevents writing an arbitrary values to the respective fields, keeping consistency on runtime
34	 * AuthenticationContext.
35	 *
36	 * @see AuthenticationContext
37	 */
38	public class JsAuthenticationContext extends AbstractJSObjectWrapper<AuthenticationContext> {
39	
40	    public JsAuthenticationContext(AuthenticationContext wrapped) {
41	        super(wrapped);
42	    }
43	
44	    @Override
45	    public Object getMember(String name) {
46	
47	        switch (name) {
48	            case FrameworkConstants.JSAttributes.JS_REQUESTED_ACR:
49	                return getWrapped().getRequestedAcr();
50	            case FrameworkConstants.JSAttributes.JS_LAST_AUTHENTICATED_USER:
51	                return new JsAuthenticatedUser(getWrapped().getLastAuthenticatedUser());
52	            case FrameworkConstants.JSAttributes.JS_TENANT_DOMAIN:
53	                return getWrapped().getTenantDomain();
54	            case FrameworkConstants.JSAttributes.JS_INITIAL_REQUEST:
55	                return new JsServletRequest(getWrapped().getInitialRequest());
56	            case FrameworkConstants.JSAttributes.JS_REQUEST:
57	                return new JsServletRequest(getWrapped().getRequest());
58	            case FrameworkConstants.JSAttributes.JS_RESPONSE:
59	                return new JsServletResponse(getWrapped().getResponse());
60	            default:
61	                return super.getMember(name);
62	        }
63	    }
64	
65	    @Override
66	    public boolean hasMember(String name) {
67	
68	        switch (name) {
69	            case FrameworkConstants.JSAttributes.JS_REQUESTED_ACR:
70	                return getWrapped().getRequestedAcr() != null;
71	            case FrameworkConstants.JSAttributes.JS_LAST_AUTHENTICATED_USER:
72	                return getWrapped().getLastAuthenticatedUser() != null;
73	            case FrameworkConstants.JSAttributes.JS_TENANT_DOMAIN:
74	                return getWrapped().getTenantDomain() != null;
75	            case FrameworkConstants.JSAttributes.JS_INITIAL_REQUEST:
76	                return getWrapped().getInitialRequest() != null;
77	            case FrameworkConstants.JSAttributes.JS_REQUEST:
78	                return getWrapped().getRequest() != null;
79	            case FrameworkConstants.JSAttributes.JS_RESPONSE:
80	                return getWrapped().getResponse() != null;
81	            default:
82	                return super.hasMember(name);
83	        }
84	    }
85	
86	    @Override
87	    public void removeMember(String name) {
88	
89	        switch (name) {
90	            case FrameworkConstants.JSAttributes.JS_SELECTED_ACR:
91	                getWrapped().setSelectedAcr(null);
92	                break;
93	            default:
94	                super.removeMember(name);
95	        }
96	    }
97	
98	    @Override
99	    public void setMember(String name, Object value) {
100	
101	        switch (name) {
102	            case FrameworkConstants.JSAttributes.JS_SELECTED_ACR:
103	                getWrapped().setSelectedAcr(String.valueOf(value));
104	                break;
105	            default:
106	                super.setMember(name, value);
107	        }
108	    }
109	}
