21	import org.apache.commons.logging.Log;
22	import org.apache.commons.logging.LogFactory;
23	
24	/**
25	 * Logger For javascript engine.
26	 * Supports console.log, console.warn, console.error and console.info
27	 */
28	public class JsLogger {
29	
30	    private static final Log logger = LogFactory.getLog(JsLogger.class);
31	
32	    /**
33	     * Logs with list of objects.
34	     * @param values
35	     */
36	    public void log(Object... values) {
37	
38	        if (values != null) {
39	            if (values.length <= 0) {
40	                logger.debug("");
41	            } else if (values.length == 1) {
42	                logger.debug(String.valueOf(values[0]));
43	            } else {
44	                StringBuilder stringBuilder = new StringBuilder();
45	                for (Object value : values) {
46	                    stringBuilder.append(String.valueOf(value));
47	                    stringBuilder.append(" ");
48	                }
49	                logger.debug(stringBuilder.toString());
50	            }
51	        }
52	    }
53	
54	    public void debug(String value) {
55	        logger.debug(value);
56	    }
57	
58	    public void info(String value) {
59	        logger.info(value);
60	    }
61	
62	    public void error(String value) {
63	        logger.error(value);
64	    }
65	
66	    public void log(String message, Object... values) {
67	
68	    }
69	}
