21	import jdk.nashorn.api.scripting.AbstractJSObject;
22	
23	import javax.servlet.http.HttpServletResponse;
24	import java.util.Map;
25	
26	/**
27	 * Javascript wrapper for Java level HashMap of HTTP headers.
28	 * This provides controlled access to HTTPServletResponse object's headers via provided javascript native syntax.
29	 * Also it prevents writing an arbitrary values to the respective fields, keeping consistency on runtime.
30	 */
31	public class JsHeaders extends AbstractJSObject {
32	
33	    private Map wrapped;
34	    private HttpServletResponse response;
35	
36	    public JsHeaders(Map wrapped, HttpServletResponse response) {
37	
38	        this.wrapped = wrapped;
39	        this.response = response;
40	    }
41	
42	    @Override
43	    public Object getMember(String name) {
44	
45	        if (wrapped == null) {
46	            return super.getMember(name);
47	        } else {
48	            return wrapped.get(name);
49	        }
50	    }
51	
52	    @Override
53	    public boolean hasMember(String name) {
54	
55	        if (wrapped == null) {
56	            return false;
57	        } else {
58	            return wrapped.get(name) != null;
59	        }
60	    }
61	
62	    @Override
63	    public void removeMember(String name) {
64	
65	        if (wrapped == null) {
66	            super.removeMember(name);
67	        } else {
68	            if (wrapped.containsKey(name)) {
69	                wrapped.remove(name);
70	            }
71	        }
72	    }
73	
74	    @Override
75	    public void setMember(String name, Object value) {
76	
77	        if (wrapped == null) {
78	            super.setMember(name, value);
79	        } else {
80	            wrapped.put(name, value);
81	            //adds a new header to the response.
82	            response.addHeader(name, String.valueOf(value));
83	        }
84	    }
85	}
