package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import jdk.nashorn.api.scripting.AbstractJSObject;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;

/**
 * Javascript wrapper for a view over the user attributes map, keyed by a claim URI.
 * This provides array-like (associative) access to the claim values via the javascript native syntax.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * <p>
 * The actual key used to look up the entries is derived from the wrapped {@link ClaimMapping} via the
 * provided {@link IdMapper}, allowing the same map to be exposed keyed either by local or remote claim URI.
 */
public class JsClaimView extends AbstractJSObject {

    private Map<ClaimMapping, String> wrapped;
    private IdMapper idMapper;

    public JsClaimView(Map<ClaimMapping, String> wrapped, IdMapper idMapper) {

        this.wrapped = wrapped;
        this.idMapper = idMapper;
    }

    @Override
    public Object getMember(String name) {

        if (wrapped == null) {
            return null;
        }
        for (Map.Entry<ClaimMapping, String> entry : wrapped.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                return entry.getValue();
            }
        }
        return null;
    }

    @Override
    public boolean hasMember(String name) {

        if (wrapped == null) {
            return false;
        }
        for (Map.Entry<ClaimMapping, String> entry : wrapped.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                return true;
            }
        }
        return false;
    }

    @Override
    public void setMember(String name, Object value) {

        if (wrapped == null) {
            return;
        }
        for (Map.Entry<ClaimMapping, String> entry : wrapped.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                entry.setValue(String.valueOf(value));
                return;
            }
        }
    }

    @Override
    public boolean isArray() {

        return true;
    }

    /**
     * Extracts the claim URI to be used as the key for a given {@link ClaimMapping}.
     */
    public interface IdMapper {

        String toId(ClaimMapping claimMapping);
    }
}
