package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import jdk.nashorn.api.scripting.AbstractJSObject;
import org.wso2.carbon.identity.application.authentication.framework.util.FrameworkConstants;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;
import java.util.function.Consumer;

/**
 * Javascript wrapper for the user attributes (claims) map of an authenticated user.
 * This provides controlled access to the {@code Map<ClaimMapping, String>} via provided javascript native syntax.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * context.subject.claims.push({local: "...", remote: "...", value: "..."})
 * <p>
 * instead of directly manipulating the underlying map.
 *
 * @see ClaimMapping
 */
public class JsClaimSet extends AbstractJSObject {

    private Map<ClaimMapping, String> wrapped;

    public JsClaimSet(Map<ClaimMapping, String> wrapped) {

        this.wrapped = wrapped;
    }

    @Override
    public Object getMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
                return new JsClaimView(wrapped,
                        claimMapping -> claimMapping.getLocalClaim() != null ?
                                claimMapping.getLocalClaim().getClaimUri() : null);
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
                return new JsClaimView(wrapped,
                        claimMapping -> claimMapping.getRemoteClaim() != null ?
                                claimMapping.getRemoteClaim().getClaimUri() : null);
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return (Consumer<Object>) this::push;
            default:
                return super.getMember(name);
        }
    }

    @Override
    public boolean hasMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return true;
            default:
                return super.hasMember(name);
        }
    }

    /**
     * Pushes a new claim into the wrapped user attributes map.
     * The provided claim object is expected to hold {@code local}, {@code remote} and {@code value} members.
     * If the {@code value} member is missing, no entry is added.
     *
     * @param claim the claim object provided from the javascript layer.
     */
    private void push(Object claim) {

        try {
            if (!(claim instanceof Map)) {
                JsLogger.getInstance().error("Invalid claim object provided to push. Expected a claim object with "
                        + "local, remote and value members.");
                return;
            }
            Map claimMap = (Map) claim;
            Object local = claimMap.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL);
            Object remote = claimMap.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE);
            Object value = claimMap.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_VALUE);

            if (local == null || remote == null) {
                JsLogger.getInstance().error("Malformed claim object provided to push. Both local and remote claim "
                        + "URIs are required.");
                return;
            }
            if (value == null) {
                JsLogger.getInstance().error("Malformed claim object provided to push. The value member is required.");
                return;
            }
            ClaimMapping claimMapping =
                    ClaimMapping.build(String.valueOf(local), String.valueOf(remote), null, false);
            wrapped.put(claimMapping, String.valueOf(value));
        } catch (Exception e) {
            JsLogger.getInstance().error("Error while pushing the claim to the user attributes. " + e.getMessage());
        }
    }

    /**
     * Returns whether the wrapped user attributes map is empty.
     *
     * @return true when there are no user attributes.
     */
    public boolean isEmpty() {

        return wrapped == null || wrapped.isEmpty();
    }
}
