+import javax.script.*;
+import jdk.nashorn.api.scripting.AbstractJSObject;
+import java.util.*;
+import java.util.function.Consumer;
+
+public class TestFlow {
+  // stand-ins mirroring ClaimMapping equality (local+remote based)
+  static class CM {
+    String local, remote;
+    CM(String l, String r){local=l;remote=r;}
+    public boolean equals(Object o){ if(!(o instanceof CM))return false; CM c=(CM)o;
+      return Objects.equals(local,c.local)&&Objects.equals(remote,c.remote);}
+    public int hashCode(){return Objects.hashCode(local)*31+Objects.hashCode(remote);}
+  }
+  static class View extends AbstractJSObject {
+    Map<CM,String> w; java.util.function.Function<CM,String> id;
+    View(Map<CM,String> w, java.util.function.Function<CM,String> id){this.w=w;this.id=id;}
+    public Object getMember(String n){ for(Map.Entry<CM,String> e:w.entrySet()) if(n.equals(id.apply(e.getKey()))) return e.getValue(); return null;}
+    public void setMember(String n,Object v){ for(Map.Entry<CM,String> e:w.entrySet()) if(n.equals(id.apply(e.getKey()))){e.setValue(String.valueOf(v));return;}}
+    public boolean isArray(){return true;}
+  }
+  static class ClaimSet extends AbstractJSObject {
+    Map<CM,String> w;
+    ClaimSet(Map<CM,String> w){this.w=w;}
+    public Object getMember(String n){
+      switch(n){
+        case "local": return new View(w, c->c.local);
+        case "remote": return new View(w, c->c.remote);
+        case "push": return (Consumer<Object>) this::push;
+        default: return super.getMember(n);
+      }
+    }
+    void push(Object claim){
+      if(!(claim instanceof Map)) return;
+      Map m=(Map)claim;
+      Object l=m.get("local"), r=m.get("remote"), v=m.get("value");
+      if(l==null||r==null||v==null) return;
+      w.put(new CM(String.valueOf(l),String.valueOf(r)), String.valueOf(v));
+    }
+  }
+  public static void main(String[] a) throws Exception {
+    ScriptEngine e = new ScriptEngineManager().getEngineByName("nashorn");
+    Map<CM,String> attrs = new HashMap<>();
+    attrs.put(new CM("http://local/email","emailRemote"), "old@x.com");
+    ClaimSet cs = new ClaimSet(attrs);
+    e.put("claims", cs);
+    // read via local view
+    e.eval("print('read local: ' + claims.local['http://local/email'])");
+    // write via local view
+    e.eval("claims.local['http://local/email'] = 'new@x.com'");
+    // push a new claim
+    e.eval("claims.push({local:'http://local/age', remote:'ageRemote', value:'30'})");
+    // push malformed (no value)
+    e.eval("claims.push({local:'http://local/bad', remote:'badRemote'})");
+    System.out.println("email persisted: " + attrs.get(new CM("http://local/email","emailRemote")));
+    System.out.println("age persisted: " + attrs.get(new CM("http://local/age","ageRemote")));
+    System.out.println("bad added? " + attrs.containsKey(new CM("http://local/bad","badRemote")));
+    System.out.println("size: " + attrs.size());
+  }
+}
